-- READ-ONLY post-check for migration A (run it after the migration, the same way as the pre-check). Compare the counts with the pre-check.
BEGIN READ ONLY;
SELECT current_database() AS database, current_setting('transaction_read_only') AS read_only;
SELECT count(*) AS applied, count(*) FILTER (WHERE finished_at IS NULL) AS unfinished, max(migration_name) AS tail FROM _prisma_migrations;   -- expect 19, 0, 20261020100000_role_simplification_admin_actors
SELECT count(*) AS new_columns, count(*) FILTER (WHERE is_nullable = 'YES') AS nullable FROM information_schema.columns WHERE (table_name, column_name) IN (('delivery_assignments','operatedByUserId'),('delivery_assignments','takenOverFromDriverId'),('delivery_proofs','verifiedByUserId'),('delivery_attempts','operatedByUserId'),('mess_delivery_runs','claimedByUserId'),('mess_delivery_runs','takenOverFromEmployeeId'),('mess_delivery_stops','handedOverByUserId'));   -- expect 7, 7
SELECT count(*) AS foreign_keys, count(*) FILTER (WHERE confdeltype = 'r') AS restrict_fks FROM pg_constraint WHERE contype = 'f' AND conname IN ('delivery_assignments_operatedByUserId_fkey','delivery_assignments_takenOverFromDriverId_fkey','delivery_proofs_verifiedByUserId_fkey','delivery_attempts_operatedByUserId_fkey','mess_delivery_runs_claimedByUserId_fkey','mess_delivery_runs_takenOverFromEmployeeId_fkey','mess_delivery_stops_handedOverByUserId_fkey');   -- expect 7, 7
SELECT count(*) AS check_constraints FROM pg_constraint WHERE conname IN ('delivery_assignments_one_owner_ck','delivery_assignments_takeover_ck','delivery_proofs_pin_ck','delivery_attempts_one_owner_ck','mess_runs_claim_ck','mess_runs_takeover_ck','mess_stops_handed_ck');   -- expect 7
SELECT count(*) AS new_index FROM pg_indexes WHERE indexname = 'delivery_assignments_operatedByUserId_idx';   -- expect 1
SELECT (SELECT count(*) FROM delivery_assignments) AS delivery_assignments, (SELECT count(*) FROM delivery_proofs) AS delivery_proofs, (SELECT count(*) FROM delivery_attempts) AS delivery_attempts, (SELECT count(*) FROM mess_delivery_runs) AS mess_delivery_runs, (SELECT count(*) FROM mess_delivery_stops) AS mess_delivery_stops;   -- expect the pre-check numbers
SELECT (SELECT count(*) FROM delivery_assignments WHERE "operatedByUserId" IS NOT NULL OR "takenOverFromDriverId" IS NOT NULL) AS a, (SELECT count(*) FROM delivery_proofs WHERE "verifiedByUserId" IS NOT NULL) AS p, (SELECT count(*) FROM delivery_attempts WHERE "operatedByUserId" IS NOT NULL) AS t, (SELECT count(*) FROM mess_delivery_runs WHERE "claimedByUserId" IS NOT NULL OR "takenOverFromEmployeeId" IS NOT NULL) AS r, (SELECT count(*) FROM mess_delivery_stops WHERE "handedOverByUserId" IS NOT NULL) AS s;   -- expect 0, 0, 0, 0, 0 right after the migration
ROLLBACK;
